"""Demo 1: Uniform Intertwining Verification Across Arities.

Confirms the single relabelling phi(k)=k+1 intertwines the active-sites rule
S_m(k)=[1,...,m*k+1] and the shifted rule T_m(k)=[2,...,m*(k-1)+2] for many
(m, a): T_m(phi(a)) equals phi applied elementwise to S_m(a).
"""
from __future__ import annotations
from typing import List

def sites_rule(m: int, k: int) -> List[int]:
    return list(range(1, m * k + 2))

def shifted_rule(m: int, k: int) -> List[int]:
    return list(range(2, (m * k - m + 1) + 2))

def relabel(k: int) -> int:
    return k + 1

def check_intertwining(max_m: int = 5, max_a: int = 10) -> bool:
    ok = True
    for m in range(1, max_m + 1):
        for a in range(0, max_a + 1):
            lhs = shifted_rule(m, relabel(a))
            rhs = [relabel(x) for x in sites_rule(m, a)]
            match = lhs == rhs
            ok = ok and match
            print(f"m={m} a={a}: T_m(a+1)={lhs}  phi[S_m(a)]={rhs}  ok={match}")
    return ok

if __name__ == "__main__":
    print("all identities hold:", check_intertwining())

"""Demo 2: Dual-Encoding Counting Sequence Generator.

Unrolls both generating trees (active-sites rooted at 1, shifted rooted at 2)
and prints their level counts, showing they agree for every arity m and
reproducing 1,2,5,14,42 (m=1, Catalan); 1,3,15,113,1273 (m=2);
1,4,34,586,21721 (m=3).
"""
from __future__ import annotations
from typing import Callable, List

def sites_rule(m: int, k: int) -> List[int]:
    return list(range(1, m * k + 2))

def shifted_rule(m: int, k: int) -> List[int]:
    return list(range(2, (m * k - m + 1) + 2))

def level_count(succ: Callable[[int], List[int]], root: int, depth: int) -> int:
    labels = [root]
    for _ in range(depth):
        nxt: List[int] = []
        for lab in labels:
            nxt.extend(succ(lab))
        labels = nxt
    return len(labels)

def sequences(max_m: int = 3, depth: int = 4) -> None:
    for m in range(1, max_m + 1):
        s = [level_count(lambda k: sites_rule(m, k), 1, d) for d in range(depth + 1)]
        t = [level_count(lambda k: shifted_rule(m, k), 2, d) for d in range(depth + 1)]
        print(f"m={m}: sites={s}  shifted={t}  agree={s == t}")

if __name__ == "__main__":
    sequences()

"""Demo 3: Refined Statistic Transport Histogram.

Demonstrates refined equinumerosity: the multiset of labels at each depth of the
shifted tree is exactly the multiset of active-sites labels with 1 added to each.
Any label statistic is therefore transported identically level by level.
"""
from __future__ import annotations
from collections import Counter
from typing import Callable, List

def sites_rule(m: int, k: int) -> List[int]:
    return list(range(1, m * k + 2))

def shifted_rule(m: int, k: int) -> List[int]:
    return list(range(2, (m * k - m + 1) + 2))

def level_labels(succ: Callable[[int], List[int]], root: int, depth: int) -> List[int]:
    labels = [root]
    for _ in range(depth):
        nxt: List[int] = []
        for lab in labels:
            nxt.extend(succ(lab))
        labels = nxt
    return labels

def refined(m: int = 2, depth: int = 3) -> None:
    for d in range(depth + 1):
        s = Counter(level_labels(lambda k: sites_rule(m, k), 1, d))
        t = Counter(level_labels(lambda k: shifted_rule(m, k), 2, d))
        shifted_from_s = Counter({k + 1: v for k, v in s.items()})
        print(f"level {d}: sites hist={dict(sorted(s.items()))}")
        print(f"         shift hist={dict(sorted(t.items()))}  transported={t == shifted_from_s}")

if __name__ == "__main__":
    refined()

